public BigDecimal bulkLineTotal(BigDecimal unitPrice, int qty) {
    if (unitPrice == null || unitPrice.signum() < 0 || qty <= 0) throw new IllegalArgumentException("invalid line");
    BigDecimal line = unitPrice.multiply(BigDecimal.valueOf(qty));
    if (qty >= 10) line = line.multiply(new BigDecimal("0.95"));
